"""A dropped upload response must reuse generated bytes, never rerun the graph."""

import hashlib
import io

import requests
from imprint_worker.client import Client


def test_delivery_rewinds_existing_media_after_lost_response(monkeypatch):
    monkeypatch.setattr("imprint_worker.client.time.sleep", lambda _: None)
    client = Client("https://example.test", "session", "test-token")
    received = []

    def request(method, url, **kwargs):
        received.append(kwargs["data"].read())
        if len(received) == 1:
            raise requests.ConnectionError("Response lost after server stored the upload")
        response = requests.Response()
        response.status_code = 200
        return response

    monkeypatch.setattr(client.http, "request", request)
    client.call("PUT", "/result", data=io.BytesIO(b"existing generated bytes"))
    assert received == [b"existing generated bytes", b"existing generated bytes"]


def test_results_go_to_storage_without_the_session_token_and_rewind(monkeypatch, tmp_path):
    monkeypatch.setattr("imprint_worker.client.time.sleep", lambda _: None)
    client = Client("https://example.test", "session", "test-token")
    result = tmp_path / "result.mp4"
    result.write_bytes(b"existing generated bytes")
    tickets, sent = [], []

    def call(method, path, **kwargs):
        tickets.append((path, kwargs["json"]))
        response = requests.Response()
        response._content = (
            b'{"method": "PUT", "url": "https://storage.test/r", "headers": {"h": "1"}}'
        )
        return response

    def storage(method, url, **kwargs):
        sent.append((kwargs["data"].read(), kwargs["headers"]))
        if len(sent) == 1:
            raise requests.ConnectionError("Response lost after storage kept the bytes")
        response = requests.Response()
        response.status_code = 200
        return response

    monkeypatch.setattr(client, "call", call)
    monkeypatch.setattr("imprint_worker.client.requests.request", storage)
    client.store("/attempts/a", "result.mp4", result)
    digest = hashlib.sha256(b"existing generated bytes").hexdigest()
    assert (
        tickets == [("/attempts/a/results/result.mp4/upload", {"sha256": digest, "bytes": 24})] * 2
    )
    assert sent == [(b"existing generated bytes", {"h": "1"})] * 2
